data.source:
* {
	box-sizing: border-box;
}

/**
 ** Hard normalise elements
 */
html,body,div,span,applet,object,iframe,h1,h2,h3,h4,h5,h6,p,blockquote,pre,a,abbr,acronym,address,big,cite,code,del,dfn,em,img,ins,kbd,q,s,samp,small,strike,strong,sub,sup,tt,var,b,u,i,center,dl,dt,dd,ol,ul,/* li ,*/fieldset,form,label,legend,table,caption,tbody,tfoot,thead,tr,th,td,article,aside,canvas,details,embed,figure,figcaption,footer,header,hgroup,menu,nav,output,ruby,section,summary,time,mark,audio,video {
	margin: 0;
	padding: 0;
}

:root,
html,
body {
	min-height: 100%;
	height: auto;

	/**
     ** Prevent font size shifting on IOS.
     */
	-webkit-text-size-adjust: 100%;

	/**
     ** Better tab size.
     */
	-moz-tab-size: 4;
	tab-size: 4;

	/**
	** Better fallback fonts.
	*/
	// prettier-ignore
	font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI','Helvetica Neue',Helvetica,Arial,sans-serif,'Apple Color Emoji','Segoe UI Emoji','Segoe UI Symbol';
}

hr {
	/**
    ** Fix firefox weirdness: https://bugzilla.mozilla.org/show_bug.cgi?id=190655
    */
	height: 0;
	color: inherit;
}

/**
 ** Normalise italics
 */
em,
i,
cite,
q,
address,
dfn,
var {
	font-style: italic;
}

/**
 ** Stop line height being effected
 */
sub,
sup {
	font-size: 75%;
	line-height: 0;
	position: relative;
	vertical-align: baseline;
}

sub {
	bottom: -0.25em;
}

sup {
	top: -0.5em;
}

u {
	text-decoration: underline;
}

button,
[type='button'],
[type='reset'],
[type='submit'] {
	/**
    ** Correct the inability to style clickable types in iOS and Safari
    */
	-webkit-appearance: button;

	/**
    ** Set pointer type
    */
	cursor: pointer;
}

/**
 ** Remove styling for invalid elements
 *  (https://github.com/mozilla/gecko-dev/blob/2f9eacd9d3d995c937b4251a5557d95d494c9be1/layout/style/res/forms.css#L728-L737)
 */
:-moz-ui-invalid {
	box-shadow: none;
}

/**
 ** Add the correct vertical alignment in Chrome and Firefox
 */
progress {
	vertical-align: baseline;
}

/**
 ** Correct the cursor style of increment and decrement buttons in Safari
 */
::-webkit-inner-spin-button,
::-webkit-outer-spin-button {
	height: auto;
}

::-webkit-file-upload-button {
	/**
     ** Correct the inability to style clickable types in iOS and Safari
     */
	-webkit-appearance: button;

	/**
     ** Change font properties to 'inherit' in Safari
     */
	font: inherit;
}

/**
 ** Add the correct display in Chrome and Safari
 */
summary {
	display: list-item;
}

/**
 ** Contain overflow on specific elements (opinions)
 */
figure,
pre {
	overflow-x: auto;
}

/**
 ** Remove all animations for those that want them to be off
 */
@media (prefers-reduced-motion: reduce) {
	html {
		scroll-behavior: auto;
	}

	*,
	*::before,
	*::after {
		animation-duration: 0.01ms !important;
		animation-iteration-count: 1 !important;
		transition-duration: 0.01ms !important;
		scroll-behavior: auto !important;
	}
}

/**
 ** Ensure certain elements are set to block by default
 */
article,
aside,
details,
figcaption,
figure,
footer,
header,
hgroup,
menu,
nav,
section {
	display: block;
}

data..label:
color: var(--fg-c);
font-family: var(--font);
font-size: var(--font-xs);

data..center:
justify-content: center;
text-align: center;
margin: 0 auto;

data..row:
display: flex;
flex-direction: row;
align-items: center;

data..col:
display: flex;
flex-direction: column;
align-items: center;

data..btn:
width: fit-content;
padding: var(--padding) calc(var(--padding) * 3);
color: var(--fg-a);
background: var(--bg-b);
outline: 1px solid var(--bg-b);
border: none;
border-radius: var(--radius);
box-shadow: var(--shadow-sm);
transition: 0.1s ease-out;
